import { sanitizeHtml } from '@xala-technologies/platform-ui/utils';

function SafeContent({ htmlContent }) {
  const sanitized = sanitizeHtml(htmlContent);
  return (
    <div dangerouslySetInnerHTML={{ __html: sanitized }} />
  );
}

import { sanitizeHtml } from '@xala-technologies/platform-ui/utils';

function UserInput({ value, onChange }) {
  const handleChange = (e) => {
    const sanitized = sanitizeHtml(e.target.value);
    onChange(sanitized);
  };

  return (
    <Textfield
      data-size="medium"
      value={value}
      onChange={handleChange}
    />
  );
}

function SafeLink({ url, children }) {
  // Sanitize URL (handled by platform package)
  const sanitizedUrl = sanitizeUrl(url);

  return (
    <Link 
      href={sanitizedUrl}
      rel="noopener noreferrer"
      target="_blank"
    >
      {children}
    </Link>
  );
}

import { sanitizeHtml } from '@xala-technologies/platform-ui/utils';

function SafeContent({ html }) {
  const sanitized = sanitizeHtml(html);
  return <div dangerouslySetInnerHTML={{ __html: sanitized }} />;
}

function SecureInput({ value, onChange }) {
  const handleChange = (e) => {
    const sanitized = e.target.value.replace(/[<>]/g, '');
    onChange(sanitized);
  };

  return (
    <Textfield
      data-size="medium"
      value={value}
      onChange={handleChange}
      maxLength={100}
    />
  );
}
